typedef struct { void (*fn)(void *ctx, const Event *e); void *ctx; } Handler;
Handler handlers[MAX_OBSERVERS]; size_t n_handlers;
int subject_subscribe(void (*fn)(void *, const Event *), void *ctx) {
    if (n_handlers == MAX_OBSERVERS) return -1;   /* report, never drop silently */
    handlers[n_handlers++] = (Handler){ fn, ctx };
    return 0;
}
void subject_notify(const Event *e) {
    Handler snap[MAX_OBSERVERS];
    memcpy(snap, handlers, n_handlers * sizeof *snap);  /* handlers may unsubscribe */
    for (size_t i = 0; i < n_handlers; ++i) snap[i].fn(snap[i].ctx, e);
}

